'use strict';

class LibraryNavigator {
  constructor(saved) {
    const source = saved && typeof saved === 'object' ? saved : {};
    this._loans = Array.isArray(source.loans) &&
      source.loans.every((value) => typeof value === 'string' && value.length > 0)
      ? source.loans.slice()
      : [];
    this._section = source.section === null ||
      (typeof source.section === 'string' && source.section.length > 0)
      ? source.section
      : null;
    this._sections = [];
  }

  setSections(sections) {
    if (!Array.isArray(sections)) throw new TypeError('sections must be an array');
    const copy = [];
    const ids = new Set();
    for (const section of sections) {
      if (!section || typeof section !== 'object' || Array.isArray(section) ||
          typeof section.id !== 'string' || section.id.trim().length === 0 ||
          typeof section.label !== 'string' || section.label.trim().length === 0) {
        throw new TypeError('invalid section');
      }
      ids.add(section.id);
      copy.push({ id: section.id, label: section.label });
    }
    this._sections = copy;
    if (this._section !== null && !ids.has(this._section)) this._section = null;
    return this;
  }

  selectSection(id) {
    if (!this._sections.some((section) => section.id === id)) {
      throw new RangeError('unknown section');
    }
    this._section = id;
    return '/sections/' + encodeURIComponent(id);
  }

  addLoan(code) {
    if (typeof code !== 'string' || code.trim().length === 0) {
      throw new TypeError('code must be a non-empty string');
    }
    this._loans.push(code.trim());
    return this._loans.length;
  }

  loanBadge() {
    return String(this._loans.length);
  }

  loansRoute() {
    return '/account/loans';
  }

  snapshot() {
    return {
      loans: this._loans.slice(),
      section: this._section,
      sections: this._sections.map((section) => ({
        id: section.id,
        label: section.label
      }))
    };
  }
}

module.exports = { LibraryNavigator };

