'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['LibraryNavigator']);
const { LibraryNavigator } = api;

const savedLoans = ['L1', ' L2 '];
const saved = { loans: savedLoans, section: 'fiction' };
const nav = new LibraryNavigator(saved);
savedLoans.push('later');
saved.section = 'changed';
assert.deepEqual(nav.snapshot(), { loans: ['L1', ' L2 '], section: 'fiction', sections: [] });
assert.equal(nav.loanBadge(), '2');
assert.equal(nav.loansRoute(), '/account/loans');

const sections = [{ id: 'fiction', label: 'Fiction' }, { id: 'a/b c', label: 'Special' }];
assert.equal(nav.setSections(sections), nav);
sections[0].label = 'mutated';
sections.push({ id: 'extra', label: 'Extra' });
assert.deepEqual(nav.snapshot().sections, [
  { id: 'fiction', label: 'Fiction' },
  { id: 'a/b c', label: 'Special' }
]);
assert.equal(nav.selectSection('a/b c'), '/sections/a%2Fb%20c');
assert.equal(nav.snapshot().section, 'a/b c');
assert.throws(() => nav.selectSection('missing'), RangeError);
assert.equal(nav.snapshot().section, 'a/b c');

const beforeInvalid = nav.snapshot();
for (const bad of [null, {}, [null], [{}], [{ id: '', label: 'x' }], [{ id: 'x', label: ' ' }], [{ id: 'x', label: 'X' }, { id: 'x', label: 'Y' }]]) {
  assert.throws(() => nav.setSections(bad), TypeError);
  assert.deepEqual(nav.snapshot(), beforeInvalid);
}
assert.equal(nav.setSections([{ id: 'other', label: 'Other' }]), nav);
assert.equal(nav.snapshot().section, null);

for (const bad of [null, 3, '', '   ']) {
  const count = nav.snapshot().loans.length;
  assert.throws(() => nav.addLoan(bad), TypeError);
  assert.equal(nav.snapshot().loans.length, count);
}
assert.equal(nav.addLoan('  NEW  '), 3);
assert.equal(nav.addLoan('NEW'), 4);
assert.deepEqual(nav.snapshot().loans, ['L1', ' L2 ', 'NEW', 'NEW']);
const snap = nav.snapshot();
snap.loans[0] = 'changed';
snap.sections[0].label = 'changed';
snap.sections.push({ id: 'x', label: 'X' });
assert.deepEqual(nav.snapshot(), {
  loans: ['L1', ' L2 ', 'NEW', 'NEW'],
  section: null,
  sections: [{ id: 'other', label: 'Other' }]
});

assert.deepEqual(new LibraryNavigator().snapshot(), { loans: [], section: null, sections: [] });
assert.deepEqual(new LibraryNavigator({ loans: ['ok', ''], section: 7 }).snapshot(), { loans: [], section: null, sections: [] });
assert.deepEqual(new LibraryNavigator({ loans: 'bad', section: 'valid' }).snapshot(), { loans: [], section: 'valid', sections: [] });
assert.deepEqual(new LibraryNavigator({ loans: ['A'], section: '' }).snapshot(), { loans: ['A'], section: null, sections: [] });

